-- Owner dashboard tables on Cloudflare D1 (database `content-dashboard`),
-- moved from Supabase project ffcrulihwcjksmjjpwal on 2026-10-11.
--
-- Same tables, columns, keys and checks as the Supabase schema
-- (schema*.sql and supabase/migrations/). Type mapping:
--   uuid        -> TEXT (generated by the default below when not given)
--   timestamptz -> TEXT, always ISO 8601 UTC "YYYY-MM-DDTHH:MM:SS.sssZ"
--                  (lib/db.ts normalizes writes and filters, so text order = time order)
--   date        -> TEXT "YYYY-MM-DD"
--   jsonb/text[]-> TEXT holding JSON (lib/db.ts encodes/decodes)
--   boolean     -> INTEGER 0/1 (lib/db.ts converts)
--   numeric     -> REAL, int/bigint -> INTEGER
--
-- Apply: npx wrangler d1 migrations apply content-dashboard --remote

CREATE TABLE IF NOT EXISTS employees (
  id TEXT PRIMARY KEY NOT NULL DEFAULT (lower(hex(randomblob(4)) || '-' || hex(randomblob(2)) || '-4' || substr(hex(randomblob(2)), 2) || '-' || substr('89ab', 1 + (abs(random()) % 4), 1) || substr(hex(randomblob(2)), 2) || '-' || hex(randomblob(6)))),
  name TEXT NOT NULL,
  pin TEXT NOT NULL,
  avatar_color TEXT NOT NULL DEFAULT '#22c55e',
  created_at TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

CREATE TABLE IF NOT EXISTS pinterest_topics (
  id TEXT PRIMARY KEY NOT NULL,
  category TEXT NOT NULL,
  title_template TEXT NOT NULL,
  description_template TEXT NOT NULL,
  prompt_seed TEXT NOT NULL,
  times_used INTEGER DEFAULT 0,
  last_used_at TEXT,
  created_at TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);
CREATE INDEX IF NOT EXISTS idx_topics_category ON pinterest_topics(category);

CREATE TABLE IF NOT EXISTS rc_subscriptions (
  id TEXT PRIMARY KEY NOT NULL,
  app_user_id TEXT NOT NULL,
  country TEXT,
  store TEXT DEFAULT 'app_store',
  product_id TEXT,
  status TEXT NOT NULL,
  auto_renewal TEXT,
  environment TEXT DEFAULT 'production',
  purchased_at TEXT,
  expires_at TEXT,
  revenue_gross REAL DEFAULT 0,
  updated_at TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  created_at TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  app_name TEXT
);
CREATE INDEX IF NOT EXISTS idx_rc_subs_status ON rc_subscriptions(status);
CREATE INDEX IF NOT EXISTS idx_rc_subs_env ON rc_subscriptions(environment);
CREATE INDEX IF NOT EXISTS idx_rc_subs_env_purchased ON rc_subscriptions(environment, purchased_at);
CREATE INDEX IF NOT EXISTS idx_rc_subs_user ON rc_subscriptions(app_user_id);

CREATE TABLE IF NOT EXISTS rc_renewal_events (
  id TEXT PRIMARY KEY NOT NULL,
  app_user_id TEXT NOT NULL,
  app_name TEXT NOT NULL,
  product_id TEXT,
  country TEXT,
  store TEXT DEFAULT 'app_store',
  revenue REAL NOT NULL DEFAULT 0,
  occurred_at TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);
CREATE INDEX IF NOT EXISTS rc_renewal_events_occurred_idx ON rc_renewal_events(occurred_at DESC);
CREATE INDEX IF NOT EXISTS rc_renewal_events_app_idx ON rc_renewal_events(app_name, occurred_at DESC);

CREATE TABLE IF NOT EXISTS calendar_tasks (
  id TEXT PRIMARY KEY NOT NULL DEFAULT (lower(hex(randomblob(4)) || '-' || hex(randomblob(2)) || '-4' || substr(hex(randomblob(2)), 2) || '-' || substr('89ab', 1 + (abs(random()) % 4), 1) || substr(hex(randomblob(2)), 2) || '-' || hex(randomblob(6)))),
  title TEXT NOT NULL,
  description TEXT DEFAULT '',
  image_url TEXT,
  priority INTEGER NOT NULL DEFAULT 5 CHECK (priority BETWEEN 1 AND 10),
  category TEXT NOT NULL DEFAULT 'other' CHECK (category IN ('music', 'app', 'other')),
  estimate_minutes INTEGER NOT NULL DEFAULT 30 CHECK (estimate_minutes > 0),
  recurrence TEXT NOT NULL DEFAULT 'none' CHECK (recurrence IN ('none', 'weekly', 'monthly', 'yearly')),
  start_date TEXT,
  start_time TEXT DEFAULT '09:00',
  weekly_times TEXT NOT NULL DEFAULT '{}',
  monthly_day INTEGER CHECK (monthly_day BETWEEN 1 AND 31),
  yearly_month INTEGER CHECK (yearly_month BETWEEN 1 AND 12),
  yearly_day INTEGER CHECK (yearly_day BETWEEN 1 AND 31),
  deleted_at TEXT,
  created_at TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  timed INTEGER NOT NULL DEFAULT 1,
  pin_first INTEGER NOT NULL DEFAULT 0
);
CREATE INDEX IF NOT EXISTS idx_calendar_tasks_live ON calendar_tasks(created_at) WHERE deleted_at IS NULL;

CREATE TABLE IF NOT EXISTS calendar_task_completions (
  id TEXT PRIMARY KEY NOT NULL DEFAULT (lower(hex(randomblob(4)) || '-' || hex(randomblob(2)) || '-4' || substr(hex(randomblob(2)), 2) || '-' || substr('89ab', 1 + (abs(random()) % 4), 1) || substr(hex(randomblob(2)), 2) || '-' || hex(randomblob(6)))),
  task_id TEXT NOT NULL REFERENCES calendar_tasks(id) ON DELETE CASCADE,
  occurrence_date TEXT NOT NULL,
  completed_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  UNIQUE (task_id, occurrence_date)
);
CREATE INDEX IF NOT EXISTS idx_calendar_completions_date ON calendar_task_completions(occurrence_date);

CREATE TABLE IF NOT EXISTS calendar_task_skips (
  id TEXT PRIMARY KEY NOT NULL DEFAULT (lower(hex(randomblob(4)) || '-' || hex(randomblob(2)) || '-4' || substr(hex(randomblob(2)), 2) || '-' || substr('89ab', 1 + (abs(random()) % 4), 1) || substr(hex(randomblob(2)), 2) || '-' || hex(randomblob(6)))),
  task_id TEXT NOT NULL REFERENCES calendar_tasks(id) ON DELETE CASCADE,
  occurrence_date TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  UNIQUE (task_id, occurrence_date)
);
CREATE INDEX IF NOT EXISTS idx_calendar_skips_date ON calendar_task_skips(occurrence_date);

CREATE TABLE IF NOT EXISTS calendar_task_overrides (
  id TEXT PRIMARY KEY NOT NULL DEFAULT (lower(hex(randomblob(4)) || '-' || hex(randomblob(2)) || '-4' || substr(hex(randomblob(2)), 2) || '-' || substr('89ab', 1 + (abs(random()) % 4), 1) || substr(hex(randomblob(2)), 2) || '-' || hex(randomblob(6)))),
  task_id TEXT NOT NULL REFERENCES calendar_tasks(id) ON DELETE CASCADE,
  occurrence_date TEXT NOT NULL,
  display_date TEXT NOT NULL,
  start_time TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  UNIQUE (task_id, occurrence_date)
);
CREATE INDEX IF NOT EXISTS idx_calendar_overrides_original ON calendar_task_overrides(occurrence_date);
CREATE INDEX IF NOT EXISTS idx_calendar_overrides_display ON calendar_task_overrides(display_date);

CREATE TABLE IF NOT EXISTS fabi_auth_cache (
  id TEXT PRIMARY KEY NOT NULL DEFAULT 'singleton',
  token TEXT NOT NULL,
  token_expires_at TEXT NOT NULL,
  brand_uid TEXT NOT NULL,
  company_uid TEXT NOT NULL,
  store_uids TEXT NOT NULL DEFAULT '[]',
  refreshed_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

CREATE TABLE IF NOT EXISTS fabi_daily_sales (
  date TEXT NOT NULL,
  store_uid TEXT NOT NULL DEFAULT 'all',
  revenue_net INTEGER NOT NULL DEFAULT 0,
  revenue_gross INTEGER NOT NULL DEFAULT 0,
  discount_amount INTEGER NOT NULL DEFAULT 0,
  invoice_count INTEGER NOT NULL DEFAULT 0,
  fetched_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  PRIMARY KEY (date, store_uid)
);
CREATE INDEX IF NOT EXISTS fabi_daily_sales_date_idx ON fabi_daily_sales(date DESC);
